import {sources,locations,items,episode,journalLessons,initialState,unlocked,choose,enter,restoreState} from './story-data.js';
import {AdventureAudio} from './audio.js';
import {heroes,profileOptions,defaultProfile,cleanProfile,learningPlan,nextLocation} from './profile.js';
const $=s=>document.querySelector(s), music=new AdventureAudio(),KEY='choicewright:first-key:v1';
let state=initialState(),saved=null,storageOK=true,travelTimer=null,lastFocus=null,reading=false,toastTimer;
try{const raw=JSON.parse(localStorage.getItem(KEY));state=restoreState(raw);if(state.started)saved=raw;}catch{}
let audioPrefs={music:60,voice:80};try{const p=JSON.parse(localStorage.getItem(KEY+':audio'));if(p){audioPrefs.music=Math.max(0,Math.min(100,Number(p.music)||0));audioPrefs.voice=Math.max(0,Math.min(100,Number(p.voice)||0));}}catch{}
music.setVolume(audioPrefs.music/100);
const story=$('#story'),utility=$('#utility'),welcome=$('#welcome');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;$('#save-note').textContent='Progress is not saved in this browser';}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function money(n){return (n<0?'−':'')+'$'+Math.abs(n).toLocaleString('en-US');}
function vars(){const v=state.vars,p=state.profile,plan=learningPlan(p),margin=6000-2100-500-v.housing;return {...v,name:p.name,priority:profileOptions.goal.find(([id])=>id===p.goal)[1].toLowerCase(),goalText:profileOptions.goal.find(([id])=>id===p.goal)[1].toLowerCase(),questionText:profileOptions.question.find(([id])=>id===p.question)[1].toLowerCase(),focusText:plan.title.toLowerCase(),firstStop:p.question==='process'?'visit Sage at the guides’ guild':'visit Mira at the provisioner’s shop',reserve:money(v.reserve),margin:money(margin),afterRepair:money(v.reserve-3000),homeName:v.home==='willow'?'Willow Cottage':'Lantern House',reserveResult:v.reserve<3000?'The pouch cannot cover this repair. You would need a different, workable plan before proceeding.':v.reserve===3000?'The repair would use the entire pouch. Another surprise would have no cushion waiting for it.':'There is money left, but it is a thinner cushion than before. Consider whether that remaining amount is enough for your circumstances.',endingText:'The road ahead is yours: '+plan.title.toLowerCase()+'. '+plan.pace};}
function interpolate(t){const v=vars();return t.replace(/\{\{(\w+)\}\}/g,(_,k)=>esc(v[k]??''));}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function openDialog(d){lastFocus=document.activeElement;if(!d.open)d.showModal();}
function stopNarration(){window.speechSynthesis?.cancel();reading=false;$('#narrate').setAttribute('aria-pressed','false');$('#narrate').textContent='◖ Read aloud';music.duck(false);}
function closeStory(){stopNarration();story.close();$('#world').focus();}
function update(){const n=state.done.length;$('#progress').style.width=n/6*100+'%';$('#progress-label').textContent=`YOUR JOURNEY · ${n} OF 6`;const next=nextLocation(state,locations,unlocked);$('#quest-intro').textContent=state.ended?'First quest complete! Your buying plan is unlocked.':'Collect the compass, lens, and map. Face your house decision. Reach the bridge to win this first quest.';$('#objective-text').textContent=state.ended?'You earned your First Key. Continue with your own buying plan.':next?'Next: '+next.quest+'. '+(state.inventory.length<3?`${Math.min(state.inventory.length,3)}/3 tools collected.`:'Your three tools are ready.'): 'Follow the highlighted path to the bridge.';$('#next-destination').textContent=state.ended?'Open my buying plan →':next?'Go to '+next.name+' →':'Show me the way →';$('#player-label').textContent=state.profile.complete?state.profile.name.toUpperCase()+"’S QUEST":'YOUR ADVENTURE';$('#hero-token').style.backgroundPosition=(heroes.find(h=>h.id===state.profile.hero)?.index||0)*50+'% center';
 $('#pins').innerHTML=locations.map((l,i)=>{const available=unlocked(state,l),done=state.done.includes(l.id);return `<button class="pin ${done?'done':!available?'locked':'active'}" style="left:${l.x}%;top:${l.y}%" data-place="${l.id}" aria-label="${esc(l.name)}${done?', completed':available?', visit':', locked'}"><span class="pin-icon">${done?'✓':available?l.symbol:'·'}</span><span class="pin-label">${esc(l.name)}</span></button>`;}).join('');
 $('#quest-list').innerHTML=locations.map((l,i)=>`<li class="${state.done.includes(l.id)?'finished':unlocked(state,l)?'current':''}"><b>${state.done.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</b><button data-place="${l.id}">${l.quest}</button></li>`).join('');
 document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>travel(b.dataset.place));$('#items').innerHTML=items.map(i=>`<button class="item ${state.inventory.includes(i.id)?'earned':''}" data-item="${i.id}" title="${state.inventory.includes(i.id)?i.title:'Not found yet'}" aria-label="${state.inventory.includes(i.id)?i.title:'Unfound item'}">${state.inventory.includes(i.id)?i.symbol:'·'}</button>`).join('');document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const i=items.find(i=>i.id===b.dataset.item);toast(state.inventory.includes(i.id)?i.title+': '+i.text:'Explore Hearthvale to discover what belongs here.');});position();$('#map-hint').textContent=state.ended?'Your first key is earned. Open your field journal.':`Next: ${nextLocation(state,locations,unlocked)?.name||'explore the town'}`;}
function position(){$('#traveler').style.left=state.player.x+'%';$('#traveler').style.top=state.player.y+'%';}
function travel(id){if(!state.started)return;const loc=locations.find(l=>l.id===id);if(!unlocked(state,loc)){toast('First: '+loc.requires.filter(r=>!state.done.includes(r)).map(r=>locations.find(l=>l.id===r).name).join(' and '));return;}clearTimeout(travelTimer);state.player={x:loc.x+3,y:loc.y+7};position();music.effect();$('#map-hint').textContent='Walking to '+loc.name+'…';travelTimer=setTimeout(()=>{state.location=id;state.history=[];renderNode(loc.start);},450);}
function widget(type){if(type==='compare')return `<div class="numbers"><div><small>WILLOW · FICTIONAL / MONTH</small><strong>$2,400</strong><p class="small">Loan P&amp;I $1,600<br>Taxes &amp; insurance $400<br>Utilities $200 · Upkeep $200<br>HOA &amp; mortgage insurance $0 assumed</p></div><div><small>LANTERN · FICTIONAL / MONTH</small><strong>$3,300</strong><p class="small">Loan P&amp;I $2,200<br>Taxes &amp; insurance $600<br>Utilities $250 · Upkeep $250<br>HOA &amp; mortgage insurance $0 assumed</p></div></div>`;
 if(type==='monthly')return `<div class="numbers"><div><small>CHOSEN HOUSING BUDGET</small><strong>${money(state.vars.housing)}/mo</strong></div><div><small>AFTER EXPENSES &amp; SAVINGS GOAL</small><strong>${money(3400-state.vars.housing)}/mo</strong></div></div>`;
 if(type==='reserve')return `<div class="budget-control"><label for="reserve-range">Keep in my emergency pouch</label><input type="range" id="reserve-range" min="0" max="4000" step="500" value="${state.vars.reserve}"><output id="reserve-output" for="reserve-range">${money(state.vars.reserve)} reserved · ${money(4000-state.vars.reserve)} for furniture</output></div>`;
 if(type==='retired-report')return `<div class="numbers"><div><small>TRAINING REPORT · OAK ACCOUNT</small><strong>30 days late</strong><p class="small">July payment reported late.</p></div><div><small>YOUR FICTIONAL BANK RECEIPT</small><strong>Paid on time</strong><p class="small">Receipt shows payment received before the due date.</p></div></div>`;
 if(type==='roadmap')return `<ol class="buying-roadmap"><li><b>Prepare</b><span>Understand your budget and options.</span></li><li><b>Gather your team</b><span>Discuss representation and financing.</span></li><li><b>Find a home</b><span>Compare homes and make an offer.</span></li><li><b>Check the details</b><span>Inspections, financing, and contract deadlines.</span></li><li><b>Close &amp; move in</b><span>Review documents and complete the purchase.</span></li></ol>`;
 if(type==='repair')return `<div class="numbers"><div><small>YOUR EMERGENCY POUCH</small><strong>${money(state.vars.reserve)}</strong></div><div><small>FICTIONAL REPAIR ESTIMATE</small><strong>$3,000</strong></div></div>`;return '';}
function renderNode(id){stopNarration();const node=episode.nodes[id];if(!node)return;const oldItems=state.inventory.length;state.node=id;enter(state,node);if(state.inventory.length>oldItems)music.effect(node.ending?'finish':'reward');music.mood=['inspection','self-fund'].includes(id)?'tense':'explore';save();update();const loc=locations.find(l=>l.id===state.location);$('#scene-location').textContent=`${loc.name} · ${node.ending?'JOURNEY COMPLETE':'THE FIRST KEY'}`;
 $('#story-body').innerHTML=`<div class="scene-enter">${node.ending?'<div class="ending-seal">⚿</div>':''}<div class="character"><span class="sigil">${node.symbol}</span>${interpolate(node.speaker)}</div><h2>${interpolate(node.title)}</h2><div class="prose">${node.text.map(p=>`<p>${interpolate(p)}</p>`).join('')}</div>${node.widget?widget(node.widget):''}${node.lesson?`<div class="lesson"><small>PACK THIS FOR REAL LIFE</small>${node.lesson}</div>`:''}${node.ending?`<div class="complete-metrics"><span>6 places explored</span><span>4 discoveries earned</span><span>1 clearer next step</span></div>`:''}<div class="choices">${node.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><span>${i+1}</span><div><strong>${c.label}</strong>${c.detail?`<small>${c.detail}</small>`:''}</div><span>→</span></button>`).join('')}</div></div>`;
 $('#story-body').scrollTop=0;$('#back-scene').disabled=!state.history.length;$('#scene-count').textContent=`${state.done.length}/6 places complete`;$('#scene-source').hidden=!node.source;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>act(Number(b.dataset.choice)));const range=$('#reserve-range');if(range)range.oninput=()=>{$('#reserve-output').textContent=`${money(+range.value)} reserved · ${money(4000-range.value)} for furniture`;};openDialog(story);}
function act(i){const node=episode.nodes[state.node],c=node.choices[i];if(!c)return;state.history.push(JSON.stringify({...state,history:[]}));if(state.history.length>30)state.history.shift();if(node.widget==='reserve')state.vars.reserve=+$('#reserve-range').value;music.effect();if(c.to.startsWith('@')){save();closeStory();update();if(c.to==='@journal')showJournal();if(c.to==='@series')showSeries();if(c.to==='@plan')showPlan();if(c.to==='@next')goNext();return;}choose(state,c);renderNode(c.to);}
$('#back-scene').onclick=()=>{if(!state.history.length)return;const history=[...state.history],previous=JSON.parse(history.pop());const profile=state.profile;state={...previous,profile,history};renderNode(state.node);};$('#close-story').onclick=closeStory;story.addEventListener('cancel',stopNarration);
$('#narrate').onclick=()=>{if(reading){stopNarration();return;}if(!window.speechSynthesis){toast('Read-aloud is not available in this browser. All dialogue is on screen.');return;}const node=episode.nodes[state.node],u=new SpeechSynthesisUtterance([node.title,...node.text.map(interpolate),node.lesson||''].join('. '));u.rate=.96;u.pitch=.93;u.lang='en-US';u.volume=audioPrefs.voice/100;u.onend=u.onerror=()=>stopNarration();reading=true;$('#narrate').setAttribute('aria-pressed','true');$('#narrate').textContent='■ Stop reading';music.duck(true);speechSynthesis.speak(u);};
function syncSound(){document.querySelectorAll('[data-prologue-sound]').forEach(b=>b.textContent=music.on?'♫ Mute':'♫ Sound on');$('#music').setAttribute('aria-pressed',String(music.on));$('#music span').textContent=music.on?'Sound on':'Sound off';$('#music-volume').value=audioPrefs.music;$('#voice-volume').value=audioPrefs.voice;$('#music-level').textContent=audioPrefs.music+'%';$('#voice-level').textContent=audioPrefs.voice+'%';$('#sound-mute').textContent=music.on?'Mute music':'Turn music on';}
async function toggleMusic(){if(music.on)music.stop();else{const ok=await music.start();if(!ok)toast('Audio is unavailable here. You can keep playing quietly.');}syncSound();}
$('#music').onclick=toggleMusic;
function soundPanel(){if($('#prologue').open){prologuePaused=true;renderPrologue();}syncSound();openDialog($('#sound-panel'));}
$('#audio-settings').onclick=soundPanel;$('#story-volume').onclick=soundPanel;$('#close-sound').onclick=()=>$('#sound-panel').close();$('#sound-mute').onclick=toggleMusic;
function saveAudio(){try{localStorage.setItem(KEY+':audio',JSON.stringify(audioPrefs));}catch{}}
$('#music-volume').oninput=e=>{audioPrefs.music=+e.target.value;music.setVolume(audioPrefs.music/100);syncSound();saveAudio();};
$('#voice-volume').oninput=e=>{audioPrefs.voice=+e.target.value;syncSound();saveAudio();};

function utilityView(label,html){$('#utility-label').textContent=label;$('#utility-body').innerHTML=html;openDialog(utility);$('#utility-body').scrollTop=0;}
$('#close-utility').onclick=()=>{utility.close();lastFocus?.focus?.();};
function showSources(only){const entries=only?[[only,sources[only]]]:Object.entries(sources).filter(([id])=>['budget','loans','inspection'].includes(id));utilityView('THE FACTS BEHIND THE ADVENTURE',`<h2>Fantasy world. Grounded lessons.</h2><p>Characters, prices, households, and outcomes are fictional. Educational claims are linked to these U.S. consumer resources. Reviewed September 5, 2026. This is introductory education, not a loan offer, credit-score forecast, or individual financial advice.</p>${entries.map(([id,s])=>`<div class="source-card"><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a><small>${s.publisher} · ${s.note}</small></div>`).join('')}<p class="small">Your gameplay stays in this browser. There is no credit pull, report upload, or application. Read-aloud uses your browser’s voice service when available.</p>`);}
$('#sources').onclick=()=>showSources();$('#scene-source').onclick=()=>showSources(episode.nodes[state.node].source);
const nextSteps=()=>learningPlan(state.profile).tasks.map(t=>t.title+': '+t.detail);
function journalText(){return ['THE FIRST KEY — MY FIELD JOURNAL','A Choicewright adventure · Peasant Publishing','Fictional training choices, not a loan approval or credit assessment.','',...state.done.map(id=>locations.find(l=>l.id===id).quest.toUpperCase()+'\n'+journalLessons[id]),'',`Adventurer: ${state.profile.name}`,`My goal: ${learningPlan(state.profile).goal}`,`My pace: ${learningPlan(state.profile).pace}`,`Fictional monthly housing budget: ${money(state.vars.housing)}`,`Fictional reserve before repair: ${money(state.vars.reserve)}`,`Repair response: ${state.vars.resolution||'Not reached yet'}`,'','MY NEXT STEPS',...nextSteps().map((s,i)=>`${i+1}. ${s}`),'','QUESTIONS FOR MY GUIDE','What does my complete monthly housing budget look like?','Which loan features and costs are different between these options?','What happens if an inspection uncovers a repair?','What should I understand or prepare before moving forward?','','SOURCES · Reviewed September 5, 2026',...Object.entries(sources).filter(([id])=>['budget','loans','inspection'].includes(id)).map(([,s])=>s.publisher+' — '+s.title+'\n'+s.url)].join('\n');}
function downloadJournal(){const blob=new Blob([journalText()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='The-First-Key-Field-Journal.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your field journal is ready to take with you.');}
function showJournal(){utilityView('YOUR FIELD JOURNAL',`<h2>${state.ended?'Your next chapter starts here.':'Understanding, collected.'}</h2><p>${state.done.length?`${state.done.length} of 6 places explored. These are the lessons you have gathered.`:'Your journal is empty. Visit your cottage to begin collecting lessons.'}</p>${state.done.map(id=>`<div class="journal-entry"><h3>${locations.find(l=>l.id===id).quest}</h3><p>${journalLessons[id]}</p></div>`).join('')}${state.done.includes('market')?`<div class="numbers"><div><small>FICTIONAL HOUSING BUDGET</small><strong>${money(state.vars.housing)}/mo</strong></div><div><small>RESERVE BEFORE REPAIR</small><strong>${money(state.vars.reserve)}</strong></div></div>`:''}${state.ended?`<h3>Take one step into the real world</h3><ol>${nextSteps().map(s=>`<li>${s}</li>`).join('')}</ol><p>Bring this journal to a buyer or lender conversation. Use it to explain your questions and what you want to understand next.</p>`:''}<div class="utility-actions"><button class="primary" id="download-journal">Download my journal ↓</button><button class="secondary" id="share">Share the adventure ↗</button>${state.ended?'<button class="secondary" id="journal-plan">Open my buying plan →</button><button class="secondary" id="restart">Try another path</button>':''}</div><p class="small">Saved only on this device. Downloading or sharing does not send your information to an agent or lender.</p>`);$('#download-journal').onclick=downloadJournal;$('#share').onclick=share;if($('#journal-plan'))$('#journal-plan').onclick=showPlan;const restart=$('#restart');if(restart)restart.onclick=()=>{utilityView('ANOTHER PATH',`<h2>Start a fresh adventure?</h2><p>This replaces the saved journey on this device. Download your current field journal first if you want to keep it.</p><div class="utility-actions"><button id="confirm-restart" class="primary">Start fresh</button><button id="cancel-restart" class="secondary">Keep my journey</button></div>`);$('#confirm-restart').onclick=()=>{const profile=state.profile;state=initialState();state.profile=profile;state.started=true;save();utility.close();update();renderNode('letter');};$('#cancel-restart').onclick=showJournal;};}
$('#journal').onclick=showJournal;
async function share(){const data={title:'The First Key',text:'A little adventure about a big life decision. Explore Hearthvale and find your first key.',url:location.origin+location.pathname};try{if(navigator.share)await navigator.share(data);else if(navigator.clipboard){await navigator.clipboard.writeText(data.url);toast('Adventure link copied.');}else toast('Copy the address in your browser to share this adventure.');}catch(e){if(e.name!=='AbortError')toast('Copy the address in your browser to share this adventure.');}}
function showSeries(){utilityView('THE CHOICEWRIGHT COLLECTION',`<h2>One world of possibilities.</h2><p>Adventures that help you practice the decisions waiting in real life.</p><div class="series-card"><span class="eyebrow">THE LEGEND OF HOMEOWNERSHIP · PLAYABLE NOW</span><h3>The First Key</h3><p>The opening quest: gather three tools, work through a house decision, and reach the bridge.</p><button class="primary" id="return-game">${state.ended?'Return to Hearthvale':'Continue my adventure'} →</button></div><div class="series-card"><span class="eyebrow">YOUR NEXT STEP · ${state.ended?'UNLOCKED':'FINISH THE FIRST QUEST TO UNLOCK'}</span><h3>Your Buying Plan</h3><p>A personal checklist based on your goals, timing, and the questions you want answered. Update it as your situation changes.</p><button class="secondary" id="series-plan">${state.ended?'Open my plan →':'Continue my first quest →'}</button></div><div class="series-card"><span class="eyebrow">THE CREDIT COMPASS · SERIES IN DEVELOPMENT</span><h3>A number is not your story.</h3><p>A planned adventure about understanding your reports, investigating errors, building healthy habits, and recognizing credit-repair traps.</p><ol><li><b>The Hidden Ledger:</b> read a report and understand what a score represents.</li><li><b>The False Entry:</b> gather evidence and practice an accurate dispute.</li><li><b>The Steady Path:</b> work through payment and balance decisions over time.</li><li><b>The Shortcut Seller:</b> spot promises no one can guarantee.</li></ol><p class="small">Research foundation: CFPB and FTC consumer guidance. Real credit outcomes vary; this series will not promise a point increase or instant repair.</p><button class="secondary" id="credit-facts">Explore the research ↗</button></div>`);$('#return-game').onclick=()=>utility.close();$('#series-plan').onclick=()=>{if(state.ended)showPlan();else{utility.close();goNext();}};$('#credit-facts').onclick=()=>showSources('rebuild');}
$('#series').onclick=showSeries;
async function begin(sound){if(sound&&!music.on)await toggleMusic();welcome.close();if(state.profile.complete){state.started=true;save();update();if(state.ended)showPlan();else renderNode(state.node);}else showSetup(false);}
$('#begin').onclick=()=>begin(true);$('#quiet').onclick=()=>begin(false);if(saved?.started&&state.profile.complete){$('#begin').innerHTML='Continue your adventure <span>→</span>';$('#quiet').textContent='Continue without sound';}else if(saved?.started){$('.welcome-body>p').innerHTML='Your adventure has a new beginning.<br>Choose your character, then continue your saved journey.';}
welcome.addEventListener('cancel',e=>e.preventDefault());
$('#world').addEventListener('keydown',e=>{if(!state.started||story.open||utility.open||welcome.open||$('#setup').open||$('#prologue').open||$('#sound-panel').open)return;const k=e.key.toLowerCase(),dirs={arrowleft:[-2,0],a:[-2,0],arrowright:[2,0],d:[2,0],arrowup:[0,-2],w:[0,-2],arrowdown:[0,2],s:[0,2]};if(dirs[k]){e.preventDefault();state.player.x=Math.max(5,Math.min(94,state.player.x+dirs[k][0]));state.player.y=Math.max(8,Math.min(89,state.player.y+dirs[k][1]));position();save();}if(k==='e'||k==='enter'){e.preventDefault();const l=[...locations].sort((a,b)=>Math.hypot(a.x-state.player.x,a.y+7-state.player.y)-Math.hypot(b.x-state.player.x,b.y+7-state.player.y))[0];if(Math.hypot(l.x-state.player.x,l.y+7-state.player.y)<17)travel(l.id);else toast('Move closer to a marked place, or select it directly.');}});
document.addEventListener('keydown',e=>{if(story.open&&!utility.open&&!$('#sound-panel').open&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&['1','2','3'].includes(e.key)){e.preventDefault();act(+e.key-1);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopNarration();if($('#prologue').open){prologuePaused=true;renderPrologue();}if(music.on)music.ctx?.suspend();}else if(music.on)music.ctx?.resume();});
setInterval(()=>{if(state.started&&!state.ended&&!document.hidden){state.elapsed+=10;save();}},10000);
function goNext(){if(!state.started){showSetup(false);return;}if(state.ended){showPlan();return;}const next=nextLocation(state,locations,unlocked);if(next)travel(next.id);else toast('Open your field journal to see your progress.');}
$('#next-destination').onclick=goNext;
function howToPlay(){utilityView('YOUR FIRST QUEST',`<h2>From rent day to your first key.</h2><p>Your long-term adventure is buying a home. This opening quest is a short practice run that unlocks your personal buying plan.</p><ol class="how-steps"><li><b>Collect three tools.</b> Visit the provisioner, the guild, and the mapmaker’s tower.</li><li><b>Face your first house decision.</b> Visit Three-Door Lane and work through a repair surprise.</li><li><b>Reach the lantern bridge.</b> Choose a next step to earn your First Key and finish the teaser.</li></ol><div class="lesson"><small>HOW TO MOVE FORWARD</small>Tap a glowing place or use the “Go to…” button above the map. Choose an answer in each conversation. Use Previous choice to try another answer.</div><p>There is no timer and no perfect score. Thoughtful choices—including deciding to prepare longer—move the story forward.</p><div class="utility-actions"><button class="primary" id="help-next">${state.ended?'Open my buying plan':'Take me to my next stop'} →</button><button class="secondary" id="replay-intro">Replay the opening</button></div>`);$('#help-next').onclick=()=>{utility.close();goNext();};$('#replay-intro').onclick=()=>{utility.close();showPrologue(true);};}
$('#help').onclick=howToPlay;
let setupDraft=null,setupStep=0,editingProfile=false;
function showSetup(edit=false){stopNarration();editingProfile=edit;setupDraft=cleanProfile(state.profile);setupStep=0;renderSetup();openDialog($('#setup'));}
function selectOptions(key,value){return profileOptions[key].map(([v,label])=>`<option value="${v}" ${value===v?'selected':''}>${label}</option>`).join('');}
function collectSetup(){if(setupStep===0){setupDraft.name=$('#adventurer-name').value;setupDraft.charm=$('#adventurer-charm').value;}else{for(const key of ['goal','timeline','question'])setupDraft[key]=$('#profile-'+key).value;}}
function renderSetup(){const hero=heroes.find(h=>h.id===setupDraft.hero);$('#setup-body').innerHTML=`<div class="setup-top"><span class="eyebrow">${editingProfile?'MY ADVENTURER':'YOUR STORY STARTS HERE'} · ${setupStep+1} OF 2</span>${editingProfile?'<button id="cancel-profile" aria-label="Cancel changes">✕</button>':''}</div><div class="setup-content"><h2>${setupStep===0?'Every adventure needs you.':'What is on the other side of your door?'}</h2><p class="muted">${setupStep===0?'Pick a character that feels like you. All three can take every path.':'A few choices to make the journey yours. You can change them later.'}</p>${setupStep===0?`<div class="hero-grid" role="group" aria-label="Choose your adventurer">${heroes.map(h=>`<button type="button" class="hero-card ${setupDraft.hero===h.id?'selected':''}" data-hero="${h.id}" aria-pressed="${setupDraft.hero===h.id}"><span class="hero-art" style="background-position:${h.index*50}% center"></span><strong>${h.name}</strong><small>${h.line}</small><span class="hero-selected">${setupDraft.hero===h.id?'✓ Selected':'Choose'}</span></button>`).join('')}</div><div class="profile-grid"><label>What should we call you?<input id="adventurer-name" type="text" maxlength="30" autocomplete="off" value="${esc(setupDraft.name==='Adventurer'?'':setupDraft.name)}" placeholder="Name or nickname"></label><label>Bring a little luck<select id="adventurer-charm">${selectOptions('charm',setupDraft.charm)}</select></label></div>`:`<div class="profile-hero"><span class="hero-art" style="background-position:${hero.index*50}% center"></span><div><span class="eyebrow">${hero.name}</span><h3>${esc(setupDraft.name||'Adventurer')}</h3><p>${esc(profileOptions.charm.find(([v])=>v===setupDraft.charm)[1])} packed. Possibilities ahead.</p></div></div><div class="profile-fields"><label>What would a home make possible?<select id="profile-goal">${selectOptions('goal',setupDraft.goal)}</select></label><label>When might you want to make a move?<select id="profile-timeline">${selectOptions('timeline',setupDraft.timeline)}</select></label><label>What would you most like to understand?<select id="profile-question">${selectOptions('question',setupDraft.question)}</select></label></div>`}<div class="setup-actions">${setupStep?'<button class="secondary" id="setup-back">← My character</button>':'<span class="small">Your character changes the look, not your options.</span>'}<button class="primary" id="setup-next">${setupStep===0?'Make it my story →':editingProfile?'Save my changes':'Watch the opening →'}</button></div><p class="privacy-note">Your answers personalize learning and stay on this device. They are not shared with an agent or lender, and are not a mortgage assessment.</p></div>`;
 document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{collectSetup();setupDraft.hero=b.dataset.hero;music.effect();renderSetup();});if($('#cancel-profile'))$('#cancel-profile').onclick=()=>$('#setup').close();if($('#setup-back'))$('#setup-back').onclick=()=>{collectSetup();setupStep=0;renderSetup();};$('#setup-next').onclick=()=>{collectSetup();setupDraft=cleanProfile(setupDraft);if(setupStep===0){setupStep=1;renderSetup();return;}state.profile={...setupDraft,complete:true};state.vars.priority=state.profile.goal;save();update();$('#setup').close();if(editingProfile){toast('Your adventurer and buying plan are updated.');if(state.planStarted)showPlan();}else showPrologue(false);};}
$('#setup').addEventListener('cancel',e=>{if(!editingProfile)e.preventDefault();});$('#profile-button').onclick=()=>showSetup(true);
let prologueTimer=null,prologueIndex=0,prologuePaused=false,prologueReplay=false;
const openingFrames=[
 {position:'22% 72%',eyebrow:'HEARTHVALE · ANOTHER RENT DAY',title:'Work. Rent. Repeat.',text:'You work hard. Every month, another payment buys another month in a place that belongs to someone else. Tonight, you start wondering what a place of your own could look like.'},
 {position:'92% 15%',eyebrow:'A DIFFERENT CHAPTER',title:'A door with your name on it.',text:'A garden. More space. Walls you can finally paint. Buying brings responsibilities, too. You don’t need all the answers tonight—just a way to find your first ones.'},
 {position:'48% 43%',eyebrow:'YOUR MISSION',title:'Three tools. One first key.',text:'Meet Mira, Sage, and Ellis. Collect the Budget Compass, the Clear-Sight Lens, and the Homeward Map. Then face your first house decision and meet Rowan at the lantern bridge.'},
 {position:'75% 70%',eyebrow:'HOW TO WIN THIS FIRST QUEST',title:'Reach the bridge. Open what comes next.',text:'Tap a glowing place. Talk, choose, and keep going. Follow the “Go to…” button if you’re unsure. Reach the bridge to unlock a buying plan built around your goals. There is no countdown or perfect score.'}
];
function showPrologue(replay=false){stopNarration();prologueReplay=replay;prologueIndex=0;prologuePaused=false;renderPrologue();openDialog($('#prologue'));}
function renderPrologue(){clearTimeout(prologueTimer);const f=openingFrames[prologueIndex];$('#prologue-body').innerHTML=`<div class="cinema-scene" style="--scene-position:${f.position}"><div class="cinema-art ${prologuePaused?'paused':''}"></div><div class="cinema-shade"></div><div class="cinema-controls"><span class="eyebrow">THE FIRST KEY · OPENING</span><div><button data-prologue-sound>${music.on?'♫ Mute':'♫ Sound on'}</button><button id="intro-volume">Volume</button><button id="skip-opening">Skip opening →</button></div></div><div class="cinema-caption"><span class="eyebrow">${f.eyebrow}</span><h2>${f.title}</h2><p>${esc(state.profile.name)}, ${f.text.charAt(0).toLowerCase()+f.text.slice(1)}</p><div class="cinema-progress">${openingFrames.map((_,i)=>`<button data-frame="${i}" class="${i<=prologueIndex?'viewed':''}" aria-label="Opening scene ${i+1}"></button>`).join('')}</div><div class="cinema-bottom"><button id="pause-opening" class="secondary">${prologuePaused?'▶ Play':'Ⅱ Pause'}</button><span>${prologueIndex+1} / ${openingFrames.length} · Animated opening</span><button id="next-opening" class="primary">${prologueIndex===3?prologueReplay?'Back to my adventure →':'I’m ready. Let’s go →':'Next →'}</button></div></div></div>`;
 $('[data-prologue-sound]').onclick=toggleMusic;$('#intro-volume').onclick=soundPanel;$('#skip-opening').onclick=finishPrologue;$('#next-opening').onclick=()=>{if(prologueIndex===3)finishPrologue();else{prologueIndex++;renderPrologue();}};$('#pause-opening').onclick=()=>{prologuePaused=!prologuePaused;renderPrologue();};document.querySelectorAll('[data-frame]').forEach(b=>b.onclick=()=>{prologueIndex=+b.dataset.frame;renderPrologue();});if(!prologuePaused&&prologueIndex<3)prologueTimer=setTimeout(()=>{prologueIndex++;renderPrologue();},12000);}
function finishPrologue(){clearTimeout(prologueTimer);$('#prologue').close();if(prologueReplay){update();return;}state.started=true;save();update();renderNode(saved?state.node:'letter');}
$('#prologue').addEventListener('cancel',e=>{e.preventDefault();finishPrologue();});
function showPlan(){stopNarration();if(!state.ended){utility.close();goNext();return;}state.planStarted=true;save();const p=learningPlan(state.profile),done=p.tasks.filter(t=>state.planTasks.includes(t.id)).length;utilityView('YOUR NEXT CHAPTER · BUYING PLAN',`<div class="plan-heading"><span class="hero-art" style="background-position:${heroes.find(h=>h.id===state.profile.hero).index*50}% center"></span><div><span class="eyebrow">FIRST KEY EARNED</span><h2>${esc(state.profile.name)}, make it real.</h2><p>${esc(p.goal)}. ${esc(p.pace)}</p></div></div><div class="plan-focus"><span class="eyebrow">YOUR PATH</span><h3>${p.title}</h3><p>${p.why}</p></div><div class="plan-progress"><span>${done} of ${p.tasks.length} steps checked off</span><div class="progress-track"><i style="width:${done/p.tasks.length*100}%"></i></div></div><div class="plan-checklist">${p.tasks.map(t=>`<label><input type="checkbox" data-task="${t.id}" ${state.planTasks.includes(t.id)?'checked':''}><span><strong>${t.title}</strong><small>${t.detail}</small></span></label>`).join('')}</div>${done===p.tasks.length?'<div class="lesson"><small>YOUR CHECKLIST IS COMPLETE</small>You’ve marked your preparation steps complete. Bring your questions and notes into a real conversation when you’re ready.</div>':''}<div class="utility-actions"><button class="primary" id="plan-download">Download my plan ↓</button><button class="secondary" id="plan-profile">Update my information</button><button class="secondary" id="plan-map">Return to Hearthvale</button></div><p class="small">This is a self-guided learning checklist, personalized by your answers. Progress stays on this device. No application or contact request is submitted.</p>`);document.querySelectorAll('[data-task]').forEach(b=>b.onchange=()=>{state.planTasks=b.checked?[...new Set([...state.planTasks,b.dataset.task])]:state.planTasks.filter(id=>id!==b.dataset.task);save();showPlan();});$('#plan-download').onclick=downloadJournal;$('#plan-profile').onclick=()=>showSetup(true);$('#plan-map').onclick=()=>utility.close();}

window.addEventListener('pagehide',save);syncSound();update();openDialog(welcome);
